CREATE VIEW agri.v_forecast_series_serving AS
 SELECT pointer.id AS publication_pointer_id,
    publication.id AS publication_id,
    publication.publication_key,
    publication.scope_key,
    publication.manifest_checksum AS publication_manifest_checksum,
    publication.published_at,
    receipt.id AS forecast_receipt_id,
    receipt.receipt_checksum,
    receipt.issue_time,
    value.valid_time,
    value.horizon_step,
    value.point_value,
    value.p10_value,
    value.p50_value,
    value.p90_value,
    value.quantile_values,
    series.id AS series_id,
    series.series_key,
    series.source_variant_key,
    series.entity_type,
    series.entity_key,
    series.metric_name,
    series.metric_unit,
    series.spatial_cell_id,
    series.representation_kind,
    series.spatial_support_kind,
    series.source_spatial_resolution_m,
    series.output_spatial_resolution_m,
    series.source_temporal_support,
    series.output_temporal_support,
    series.aggregation_method,
    run.id AS forecast_run_id,
    snapshot.release_set_id,
    run.forecast_method,
    run.input_release_checksum,
    run.feature_checksum,
    run.model_checksum,
    run.parameter_checksum,
    run.quality_summary,
    training.id AS training_run_id,
    training.training_code_checksum,
    training.validation_checksum,
    receipt.quality_summary AS receipt_quality_summary,
    'forecast_point'::text AS serving_representation
   FROM ((((((((agri.publication_pointer pointer
     JOIN agri.forecast_publication publication ON (((publication.job_output_id = pointer.job_output_id) AND ((publication.scope_key)::text = (pointer.scope_key)::text) AND (publication.release_set_id = pointer.release_set_id) AND ((pointer.product)::text = 'forecast_series'::text))))
     JOIN agri.forecast_publication_item item ON ((item.publication_id = publication.id)))
     JOIN agri.forecast_receipt receipt ON ((receipt.id = item.forecast_receipt_id)))
     JOIN agri.forecast_value value ON ((value.forecast_receipt_id = receipt.id)))
     JOIN agri.forecast_series series ON ((series.id = receipt.series_id)))
     JOIN agri.forecast_run run ON ((run.id = receipt.forecast_run_id)))
     JOIN agri.forecast_feature_snapshot snapshot ON ((snapshot.id = run.feature_snapshot_id)))
     LEFT JOIN agri.forecast_training_run training ON ((training.id = run.training_run_id)))
  WHERE (((publication.state)::text = 'published'::text) AND ((receipt.status)::text = 'finalized'::text) AND ((run.status)::text = 'validated'::text) AND (pointer.release_set_id = snapshot.release_set_id));
